llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C67"],
      "claim": "Lefamulin, a complex polycyclic diterpenoid with lactone/ester and hydroxyl functionalities, has an absolute oral bioavailability of 25.8% in healthy adults, directly supporting F ≥ 20% for a structurally related rigid terpenoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dihydroartemisinin, a polycyclic sesquiterpene lactone with multiple rings and a peroxide bridge, shows 82% absolute oral bioavailability in healthy adults, indicating that rigid polycyclic lactone natural products can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Digitoxin, a complex polycyclic terpenoid glycoside, is essentially completely bioavailable after oral administration (>90%), demonstrating that highly complex lipophilic natural products can achieve high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Amphotericin B has poor oral bioavailability, but this is driven by its very large polyene macrolide architecture, poor permeability, low solubility, and instability—features not shared by the smaller, more lipophilic polycyclic lactone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a complex polycyclic diterpenoid-like lactone. The most structurally relevant analogues with absolute bioavailability data—lefamulin (~26%), dihydroartemisinin (~82%), and digitoxin (>90%)—all support F ≥ 20%. The main low-bioavailability analogue, amphotericin B, is a large polyene macrolide whose poor absorption mechanisms do not transfer well to this scaffold. Overall evidence favors high oral bioavailability at the 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Intestinal permeability, first-pass metabolism, and lactone stability of the query are not experimentally characterized.",
    "No exact structural analogue with measured absolute oral bioavailability was available; inferences rely on related terpenoid lactones and macrolides."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

